import logging

from ta_ue_plugin_android.uepc.datatransfer.data_transfer_kwargs import ALLOWED_ROBOT_KWARGS, ALLOWED_ROBOT_KWARGS_IPERF3
from ta_ue_plugin_android.uepc.datatransfer.data_transfer_utils import SERVER_CLOSE_DELAY_PARAM_NAME
from ta_ue_plugin_android.uepc.datatransfer.iperf_options import IPERF_SERVER_OPTIONS, IPERF_CLIENT_OPTIONS, \
    PARALLEL_STREAMS
from ta_ue_plugin_android.uepc.ue_manager_exceptions import BandwidthNotGivenException, DtConfigOptionMissingException, \
    InvalidKwargsException
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class DataTransferConfig(object):
    # pylint: disable=too-many-instance-attributes
    """Class representing parameters of data transfer"""
    CONTROL_APP_LABEL = "control_app"
    AVAILABLE_TPUT_COLLECTION_SOURCES = [CONTROL_APP_LABEL, "iperf"]

    def __init__(self, dt_name):
        """Basic initialization."""
        self.dt_name = dt_name
        self.app_server = {}
        self.duration = 0
        self.direction = ''
        self.robot_kwargs = {}
        self.iperf_options = {}
        self.iperf_path = str()
        self.iperf_mode = None
        self.iperf_version = None
        self.serial_number = None
        self.iperf_interface_name = None
        self.server_close_delay = None
        self.iperf_interval = None
        self.iperf_bind_ue_ip = None
        self.traffic_type = None
        self.tput_collection_src = "iperf"
        self.protocol = None
        self.additional_iperf_options_client = list()
        self.additional_iperf_options_server = list()
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})

    def init_me(self, duration, direction, protocol, iperf_version, robot_kwargs, **yaml_properties):
        """Method's name says everything."""
        self.iperf_version = self.get_iperf_version(robot_kwargs, iperf_version)
        self.set_duration_in_seconds(duration)
        self.set_direction(direction)
        self.set_robot_kwargs(robot_kwargs)
        self.set_protocol(protocol)
        self.set_properties_from_yaml(yaml_properties)
        self.validate_bandwidth_set_for_udp()
        self.set_iperf_options()
        return self

    def set_properties_from_yaml(self, yaml_properties):
        """Method's name says everything."""
        for prop_name, prop_value in yaml_properties.items():
            self.logger.debug('Setting property name and value from yaml: "{}": "{}"'.format(prop_name, prop_value))
            if not prop_value and getattr(self, prop_name, False):
                # property has default value set
                self.logger.debug('Property: {} has default value: {}.\n"'.format(prop_name, getattr(self, prop_name)))
                continue
            setattr(self, prop_name, prop_value)

    def validate_bandwidth_set_for_udp(self):
        """Method's name says everything."""
        if self.protocol == 'udp' and 'bandwidth' not in self.robot_kwargs:
            raise BandwidthNotGivenException("Bandwidth not defined in robot kwargs")

    def set_duration_in_seconds(self, duration):
        """Method's name says everything."""
        self.duration = duration

    def set_direction(self, direction):
        """Method's name says everything."""
        if direction not in ['ul', 'dl']:
            raise Exception("Unexpected direction: " + str(direction))
        self.direction = direction

    def is_uplink(self):
        """Method's name says everything."""
        return self.direction == 'ul'

    def is_downlink(self):
        """Method's name says everything."""
        return self.direction == 'dl'

    def set_protocol(self, protocol):
        """Method's name says everything."""
        if protocol not in ['udp', 'tcp']:
            raise Exception("Unexpected protocol: " + str(protocol))
        self.protocol = protocol

    def set_robot_kwargs(self, robot_kwargs):
        """Sets and validates keyword arguments from robot"""
        if self.iperf_version == 3:
            invalid_args = list(filter(lambda key: key not in ALLOWED_ROBOT_KWARGS_IPERF3, robot_kwargs.keys()))
        else:
            invalid_args = list(filter(lambda key: key not in ALLOWED_ROBOT_KWARGS, robot_kwargs.keys()))
        if invalid_args:
            raise InvalidKwargsException("Provided keyword arguments are invalid: {}".format("; ".join(invalid_args)))

        self.logger.debug('Setting properties from robot keyword args: {}'.format(robot_kwargs))
        self.robot_kwargs = robot_kwargs

    def get_iperf_version(self, robot_kwargs, iperf_version):
        """Method's name says everything."""
        if "iperf_version" in robot_kwargs:
            return self._get_iperf_version_from_robot_kwargs(robot_kwargs)
        return self._get_iperf_version_from_config_file(iperf_version)

    def _get_iperf_version_from_robot_kwargs(self, robot_kwargs):
        self.logger.debug("Setting iperf_version from robot kwargs")
        if not robot_kwargs['iperf_version']:
            self.logger.debug('Using default iperf version: 2')
            return 2
        iperf_version = robot_kwargs['iperf_version']
        self.logger.debug('Using iperf version from robot kwargs: {}'.format(iperf_version))
        return int(iperf_version)

    def _get_iperf_version_from_config_file(self, iperf_version):
        self.logger.debug("Setting iperf_version from config file")
        if not iperf_version:
            self.logger.debug('Using default iperf version: 2')
            return 2
        self.logger.debug('Using iperf version from yaml config: {}'.format(iperf_version))
        return int(iperf_version)

    def set_iperf_options(self):
        if self.iperf_version == 3:
            self.additional_iperf_options_client, self.additional_iperf_options_server = self.get_iperf3_options()
        else:
            self.additional_iperf_options_client, self.additional_iperf_options_server = self.get_iperf2_options()

    def get_bandwidth(self):
        """Method's name says everything."""
        if 'bandwidth' not in self.robot_kwargs:
            if self.is_tcp():
                return ''  # For TCP the bandwidth flag is optional
            if self.is_udp():
                raise Exception("bandwidth not defined in robot kwargs")
        return self.robot_kwargs['bandwidth']

    def get_duration(self):
        """Method's name says everything."""
        return self.duration

    def get_direction(self):
        """Method's name says everything."""
        return self.direction

    def get_protocol(self):
        """Method's name says everything."""
        return self.protocol

    def get_iperf_interval(self):
        """Method's name says everything."""
        if 'interval' in self.robot_kwargs:
            if float(self.robot_kwargs['interval']) == 0:
                self.logger.debug('Using default iperf interval: 1')
                return 1
            return float(self.robot_kwargs['interval'])
        if self.iperf_interval is None or float(self.iperf_interval) == 0:
            self.logger.debug('Using default iperf interval: 1')
            return 1
        self.logger.debug('Using iperf interval from yaml config: {}'.format(self.iperf_interval))
        return float(self.iperf_interval)

    def is_udp(self):
        """Method's name says everything."""
        return self.protocol == 'udp'

    def is_tcp(self):
        """Method's name says everything."""
        return self.protocol == 'tcp'

    def get_iperf_interface_name(self):
        """Get iperf_interface_name parameter from config"""
        return self.iperf_interface_name

    def is_ipv6_required(self):
        """Check if ipv6 version is required for data transfer"""
        if self.app_server['ip_version'] == 6:
            return True
        return False

    def is_parallel_streams_datatransfer(self):
        """
        Checks if dt is configured  for parallel streams > 1
        :return: bool
        """
        self.logger.debug("Checking if this is a parallel streams data transfer")
        for option in self.additional_iperf_options_client:
            if PARALLEL_STREAMS in option:
                parallel_streams_value = int(option.split()[1])
                if parallel_streams_value > 1:
                    return True
        return False

    def get_iperf_options(self, supported_options, postfix):
        """
        Get iperf option either from Start Data Transfer keyword arg or global yaml iperf_options
        :param supported_options: dictionary with supported option names and corresponding switch letters
        :param postfix: string to identify if option should be appended to server or client
        """
        options_list = []
        self.logger.debug("Trying to add iperf options based on robot keyword arguments")
        options_list = self._try_to_get_options_from_dict(self.robot_kwargs, supported_options, options_list,
                                                          postfix=postfix)
        if self.iperf_options:  # iperf_options in data_transfer yaml section
            self.logger.debug("Trying to add global iperf options based on yaml iperf_options arguments")
            options_list = self._try_to_get_options_from_dict(self.iperf_options, supported_options, options_list,
                                                              postfix=postfix)
        return options_list

    def get_iperf2_client_options(self):
        return self.get_iperf_options(IPERF_CLIENT_OPTIONS['iperf2'],
                                      IPERF_CLIENT_OPTIONS['postfix'])

    def get_iperf3_client_options(self):
        return self.get_iperf_options(IPERF_CLIENT_OPTIONS['iperf3'],
                                      IPERF_CLIENT_OPTIONS['postfix'])

    def get_iperf2_server_options(self):
        return self.get_iperf_options(IPERF_SERVER_OPTIONS['iperf2'],
                                      IPERF_SERVER_OPTIONS['postfix'])

    def get_iperf3_server_options(self):
        return self.get_iperf_options(IPERF_SERVER_OPTIONS['iperf3'],
                                      IPERF_SERVER_OPTIONS['postfix'])

    def get_iperf2_options(self):
        return self.get_iperf2_client_options(), self.get_iperf2_server_options()

    def get_iperf3_options(self):
        return self.get_iperf3_client_options(), self.get_iperf3_server_options()

    def _try_to_get_options_from_dict(self, dictionary, supported_options, options_list, postfix=None):
        for option_name, option_value in dictionary.items():
            option_without_postfix = option_name.split("_{}".format(postfix))[0]
            if option_without_postfix not in supported_options:
                continue
            option_letter = supported_options[option_without_postfix]
            if any([option_letter in option for option in options_list]):
                continue  # We don't want to duplicate options
            self.logger.debug("Adding iperf option {} to {}: {} {}".format(option_name, postfix, option_letter,
                                                                           option_value))
            if option_value is True or str(option_value).lower() == 'true':
                options_list.append(option_letter)
            else:
                options_list.append("{} {}".format(option_letter, option_value))
        return options_list

    @staticmethod
    def get_iperf_execution_file_name(version):
        return "iperf3" if version == 3 else "iperf"

    def get_corrected_iperf_path(self, version):
        """Verifies if iperf path provided in yaml data transfer confog is fullpath to binary
        and corrects it if needed"""
        win_os_sep = "\\"
        lin_os_sep = "/"
        iperf_file_name = self.get_iperf_execution_file_name(version)
        if self.iperf_path.endswith((iperf_file_name, "{}.exe".format(iperf_file_name))):
            return self.iperf_path
        if self.iperf_path.endswith((lin_os_sep, win_os_sep)):
            return self.iperf_path + iperf_file_name
        if lin_os_sep in self.iperf_path:
            return "{}{}{}".format(self.iperf_path, lin_os_sep, iperf_file_name)
        if win_os_sep in self.iperf_path:
            return "{}{}{}".format(self.iperf_path, win_os_sep, iperf_file_name)

    def has_packet_size(self):
        """
        Some option to iperf, see usage
        :return:
        """
        return 'packet_size' in self.robot_kwargs

    def get_packet_size(self):
        """
        Some option to iperf, see usage
        :return:
        """
        return self.robot_kwargs['packet_size']

    def has_max_segment_size(self):
        """
        Has max segment size.

        :return: add to iperf option -M ?
        """
        return 'max_segment_size' in self.robot_kwargs

    def get_max_segment_size(self):
        """
        Get max segment size.

        :return: iperf option -M value
        """
        if 'max_segment_size' in self.robot_kwargs:
            return self.robot_kwargs['max_segment_size']
        return None

    def has_server_close_delay(self):
        """:return:"""
        return SERVER_CLOSE_DELAY_PARAM_NAME in self.robot_kwargs or getattr(self,
                                                                             SERVER_CLOSE_DELAY_PARAM_NAME) is not None

    def get_server_close_delay(self):
        """:return: server_close_delay from robot kwargs or yaml file. Robot kwargs has priority"""
        if self.has_server_close_delay():
            if SERVER_CLOSE_DELAY_PARAM_NAME not in self.robot_kwargs:
                return self.server_close_delay
            return self.robot_kwargs[SERVER_CLOSE_DELAY_PARAM_NAME]
        raise Exception("SERVER_CLOSE_DELAY not specified")

    def has_qci_value(self):
        """
        Iperf option (port). Mapping to port in iperf options (yaml confg)
        :return:
        """
        return 'qci' in self.robot_kwargs

    def get_qci_value(self):
        """
        Iperf option (port).
        :return:
        """
        return int(self.robot_kwargs['qci'])

    def has_qci_port(self):
        """Checks if qci specified in iperf options"""
        return 'qci' in self.iperf_options.keys()

    def get_qci_port(self):
        """:return: qci_port based on mapping at iperf options at config yaml"""
        if self.has_qci_port():
            return self.iperf_options['qci'][self.get_qci_value()]
        raise DtConfigOptionMissingException('qci not specified at config yaml in iperf options')

    def get_traffic_type(self):
        """Method's name says everything."""
        return self.traffic_type

    def get_throughput_collection_source(self):
        if self.tput_collection_src not in self.AVAILABLE_TPUT_COLLECTION_SOURCES:
            raise Exception("Supported throughput collection sources: {}"
                            .format(self.AVAILABLE_TPUT_COLLECTION_SOURCES))
        return self.tput_collection_src
